  const lab=labels.map((l,i)=>{const x=L+sl*i+sl/2, y=T+H+10, t=l.length>15?l.slice(0,14)+'…':l; return rot?`<text class="ax" x="${x}" y="${y}" text-anchor="end" transform="rotate(-30 ${x} ${y})">${t}</text>`:`<text class="ax" x="${x}" y="${y}" text-anchor="middle">${t}</text>`}).join('');
