  async countries(c){
    const W=['gpay','apay'];
    const D=[
      ['Brasil','BR',['visa','mc','amex','*elo','*hipercard','*pix','*boleto','*caixa',...W]],
      ['México','MX',['visa','mc','amex','*spei','*oxxo','*paycash','*bbva','*banamex','*santander',...W]],
      ['Argentina','AR',['visa','mc','amex','diners','maestro','*argencard','*naranja','*cabal','*shopping','*cencosud','*cmr','*rapipago','*pagofacil',...W]],
      ['Colômbia','CO',['visa','mc','amex','diners','*codensa','*pse','*efecty',...W]],
      ['Peru','PE',['visa','mc','amex','diners','*yape','*pagoefectivo',...W]],
      ['Chile','CL',['visa','mc','amex','*magna','*presto','*redcompra',...W]],
      ['Uruguai','UY',['visa','mc','amex','*oca','*creditel','*lider','*abitab','*redpagos',...W]]
    ];
    const box=c.querySelector('.chips'), nm=c.querySelector('.cty-n'), L=langOf(c), ES={'Colômbia':'Colombia','Peru':'Perú','Uruguai':'Uruguay'}, nmOf=n=>L==='es'?(ES[n]||n):n;
    const ia=c.closest('.stage')&&c.closest('.stage').classList.contains('ia');
    let pick=c.querySelector('.cty-pick');
    if(ia&&!pick){
      pick=document.createElement('div'); pick.className='cty-pick'; pick.setAttribute('role','group'); pick.setAttribute('aria-label',(L==='es'?'Elige el país':'Escolha o país'));
      pick.innerHTML=D.map((d,k)=>`<button type="button" data-k="${k}" title="${nmOf(d[0])}" aria-label="${nmOf(d[0])}" aria-pressed="false">${d[1]}</button>`).join('');
      c.appendChild(pick);
      pick.addEventListener('click',e=>{const b=e.target.closest('button'); if(!b) return; c._req=+b.dataset.k; c._wake&&c._wake()});
      const cty=c.querySelector('.cty'); if(cty){ cty.setAttribute('role','button'); cty.tabIndex=0; cty.setAttribute('aria-label',(L==='es'?'Cambiar de país':'Trocar o país')); const nx=()=>{c._req=((c._ci||0)+1)%D.length; c._wake&&c._wake()}; cty.addEventListener('click',nx); cty.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault(); nx()}}) }
    }
    const wait=ms=>new Promise(r=>{const t=ms==null?null:setTimeout(r,ms); c._wake=()=>{if(t) clearTimeout(t); c._wake=null; r()}});
    const show=async k=>{
      const [country,,methods]=D[k]; c._ci=k;
      if(pick) [...pick.children].forEach((b,j)=>{b.classList.toggle('on',j===k); b.setAttribute('aria-pressed',j===k)});
      emitStep(c,k);
      [...box.children].forEach(x=>x.classList.remove('in'));
      nm.style.opacity=0; await sleep(260);
      nm.textContent=country; nm.style.opacity=1;
      box.innerHTML=methods.map(m=>{const kk=m.replace('*',''); return `<span class="lg${m[0]==='*'?' loc':''}"><img src="${LOGOS[kk]}" alt="${LOGO_NAMES[kk]}" width="54" height="40"></span>`}).join('');
      void box.offsetWidth;
      for(const ch of box.children){ch.classList.add('in'); await sleep(40)}
    };
    if(reduce){ await show(c._req!=null?c._req:0); c._req=null; if(!ia) return; for(;;){ await wait(null); if(c._req!=null){ const k=c._req; c._req=null; await show(k) } } }
    let k=c._req!=null?c._req:0, hold=c._req!=null; c._req=null;
    while(k<D.length){
      await show(k);
      if(c._req==null) await wait(hold?5000:1700);
      if(c._req!=null){ k=c._req; c._req=null; hold=true; continue }
      hold=false; k++;
    }
  },
