function tr(s,lang){ if(lang!=='es'||!s) return s; const D=I18N.es, m=/^(\s*)([\s\S]*?)(\s*)$/.exec(s), core=m[2].replace(/\s+/g,' '); if(!core) return s; let t=D.m[core]; if(t===undefined){ for(const [re,rep] of D.rx){ if(re.test(core)){ t=core.replace(re,rep); break } } } return t===undefined?s:m[1]+t+m[3] }
function langOf(el){ const r=el&&el.getRootNode&&el.getRootNode(); return (r&&r.host&&r.host.getAttribute('lang'))||'pt' }
const TR_ATTRS=['alt','aria-label','title','data-d','data-n','data-cv'];
function trNode(n,lang){ if(n.nodeType===3){ if(n.parentNode&&n.parentNode.nodeName==='STYLE') return; const v=tr(n.nodeValue,lang); if(v!==n.nodeValue) n.nodeValue=v } else if(n.nodeType===1){ for(const a of TR_ATTRS){ const v=n.getAttribute(a); if(v){ const t=tr(v,lang); if(t!==v) n.setAttribute(a,t) } } } }
function trTree(root,lang){ const tw=document.createTreeWalker(root,NodeFilter.SHOW_TEXT|NodeFilter.SHOW_ELEMENT); let n; if(root.nodeType===1) trNode(root,lang); while(n=tw.nextNode()) trNode(n,lang) }
function hydrate(root){
  root.querySelectorAll('i[data-i]').forEach(el=>{const n=el.dataset.i, cls=(el.getAttribute('class')||''); el.outerHTML=`<svg class="ic ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[n]||''}</svg>`});
  root.querySelectorAll('.gem[data-lv]').forEach(g=>g.innerHTML=gemSVG(+g.dataset.lv));
  root.querySelectorAll('[data-photo]').forEach(e=>e.style.backgroundImage=`url(${PHOTOS[e.dataset.photo]})`);
  root.querySelectorAll('.av i').forEach(e=>{e.style.background=`url(${PHOTOS.marina}) center/cover`});
  root.querySelectorAll('.ct-qr,.tqr').forEach(e=>{if(!e.innerHTML) e.innerHTML=qrSVG()});
  root.querySelectorAll('img[data-brand]').forEach(i=>i.src=BRAND[i.dataset.brand]);
  root.querySelectorAll('img[data-logo]').forEach(i=>i.src=LOGOS[i.dataset.logo]);
}
function parallax(st){ if(reduce) return; const c=st.querySelector('.canvas');
  st.addEventListener('pointermove',e=>{const r=st.getBoundingClientRect(); c.style.setProperty('--px',((e.clientX-r.left)/r.width-.5).toFixed(3)); c.style.setProperty('--py',((e.clientY-r.top)/r.height-.5).toFixed(3))});
  st.addEventListener('pointerleave',()=>{c.style.setProperty('--px',0); c.style.setProperty('--py',0)}); }
